// ---- Settings: edit these ----
const OWNER = 'sudarshan161219';
const REPO = 'lateling-reels';
const REF = 'main';
const GEMINI_MODEL = 'gemini-flash-latest';

// Products. Scheduled runs go through PRODUCTS in order, one per run. Each id is a file in reels/products.
// Put an id in twice to post about it more often. Set FORCE_PRODUCT to always use the same one.
const PRODUCTS = ['lateling', 'invo', 'signoff', 'retain', 'briefd', 'bot-meter', 'portfolio-frame', 'cutout'];
const FORCE_PRODUCT = ''; // for example 'invo'

// Videos about products other than Lateling go through this list, per product. ToolDemo needs screenshots
// in the product file and ToolTrust needs "trust" rows. Without them the run makes a ToolStory or ToolTips.
const TOOL_ROTATION = ['ToolStory', 'ToolDemo', 'ToolTips', 'ToolTrust'];

// Lateling videos. Scheduled Lateling runs go through this list in order. Set FORCE_COMPOSITION to always use the same one.
const ROTATION = ['Tips', 'BeforeAfter', 'FeatureDemo', 'Trust', 'FeatureDemo', 'BeforeAfter', 'FeatureDemo'];
const FORCE_COMPOSITION = ''; // 'BeforeAfter' | 'FeatureDemo' | 'Tips' | 'Trust', or a Tool one for other products | ''

// Scheduled FeatureDemo runs go through these in order.
const FEATURES = ['needs-attention', 'find-order', 'order-detail', 'reply-template', 'gmail-panel'];

// Optional angle for the script, for example 'guest checkouts'. Leave empty to pick one from ANGLES at random.
const TOPIC = '';

// Angles, so that two videos of the same kind do not come out alike. One is picked at random for each run.
// Every angle must be about a real feature of the app.
const ANGLES = {
  BeforeAfter: [
    'a guest checkout customer who has no account',
    'an order that shipped, but the carrier reports a delay',
    'an order that has still not shipped a week after it was placed',
    'a repeat customer writing for the second time about the same order',
    'a customer who gives only their name and no order number',
    'a Monday inbox with several where is my order emails',
  ],
  'needs-attention': [
    'orders that have not shipped after the limit you set',
    'orders the carrier reports as delayed',
    'checking the list first thing in the morning',
    'writing to the customer before they ask',
  ],
  'find-order': [
    'searching by the email address the customer wrote from',
    'finding a guest checkout order',
    'searching by name when the customer gives no order number',
    'seeing how many orders the customer has placed and how much they have spent',
  ],
  'order-detail': [
    'the estimated delivery date',
    'the tracking link',
    'Copy summary, to paste the order into a reply',
    'payment, fulfillment and delivery status in one place',
  ],
  'reply-template': [
    'variables that fill in from the order',
    'a variable that cannot be filled stays visible, so you notice before sending',
    'a template for an order the carrier has delayed',
    'a template for an order that has not shipped yet',
  ],
  'gmail-panel': [
    'answering without leaving the inbox',
    'nothing is sent automatically, you review and send',
    'the delivery status right next to the customer email',
    'inserting a saved template into the reply',
  ],
  Tips: [
    'setting delivery expectations before the customer has to ask',
    'what to put in the first reply',
    'what to do when a carrier is delayed',
    'staying on top of orders in a busy sales week',
    'keeping replies consistent with saved templates',
    'checking unshipped orders every day',
  ],
  Trust: [
    'a merchant who is careful about app permissions',
    'what happens to customer data',
    'an app that cannot break anything in the store',
    'only two permissions, both read-only',
  ],
};

// The kind of store in the example data. One is picked at random for each run.
const STORES = [
  'candles and home fragrance', 'specialty coffee', 'pet supplies', 'handmade ceramics', 'skincare',
  'kids clothing', 'stationery', 'houseplants', 'cycling accessories', 'loose leaf tea', 'jewellery', 'outdoor gear',
];
// Posting. Scheduled runs upload the reel to YouTube as a Short after the render.
// Runs started by hand only upload when POST_ON_MANUAL is true.
const POST_ON_MANUAL = false;
const YOUTUBE_PRIVACY = 'public'; // 'public' | 'unlisted' | 'private'
// ---- End of settings ----

const now = new Date();
const pick = (list) => list[Math.floor(Math.random() * list.length)];
// A run started by hand gets a random composition and feature, so test runs differ.
// Scheduled runs go through ROTATION in order. The position is kept in the workflow's static data.
const manual = $execution.mode !== 'production' && $execution.mode !== 'trigger';
const state = $getWorkflowStaticData('global');
let product = FORCE_PRODUCT || pick(PRODUCTS);
if (!manual && !FORCE_PRODUCT) {
  product = PRODUCTS[(state.products ?? 0) % PRODUCTS.length];
  state.products = (state.products ?? 0) + 1;
}
const lateling = product === 'lateling';
const forced = FORCE_COMPOSITION && FORCE_COMPOSITION.startsWith('Tool') !== lateling ? FORCE_COMPOSITION : '';

let composition;
let feature = '';
let topic = TOPIC;
let store = '';
if (lateling) {
  composition = forced || pick(['BeforeAfter', 'FeatureDemo', 'Tips', 'Trust']);
  if (!manual && !forced) {
    composition = ROTATION[(state.runs ?? 0) % ROTATION.length];
    state.runs = (state.runs ?? 0) + 1;
  }
  if (composition === 'FeatureDemo') {
    feature = pick(FEATURES);
    if (!manual) {
      feature = FEATURES[(state.demos ?? 0) % FEATURES.length];
      state.demos = (state.demos ?? 0) + 1;
    }
  }
  topic = TOPIC || pick(ANGLES[feature || composition]);
  store = pick(STORES);
} else {
  // The topic is picked from the product's own "angles" once the product file is loaded.
  composition = forced || pick(TOOL_ROTATION);
  if (!manual && !forced) {
    state.tools = state.tools ?? {};
    const i = state.tools[product] ?? 0;
    composition = TOOL_ROTATION[i % TOOL_ROTATION.length];
    state.tools[product] = i + 1;
  }
}
const promptPath = lateling ? 'prompts/script-writer.md' : 'prompts/tool-script-writer.md';
const post = !manual || POST_ON_MANUAL;

// Used as the release tag: reel-<requestId>. Must be unique for every run.
const pad = (n) => String(n).padStart(2, '0');
const requestId =
  `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}-` +
  `${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;

return [{json: {owner: OWNER, repo: REPO, ref: REF, model: GEMINI_MODEL, product, promptPath, composition, feature, topic, store, requestId,
  post, youtubePrivacy: YOUTUBE_PRIVACY}}];

// Builds the Gemini request: the prompt file from the repo is the system instruction.
// For products other than Lateling, the product file is added to the request as JSON.
const cfg = $('Config').first().json;
const prompt = $('Fetch prompt').first().json.data;
if (typeof prompt !== 'string' || prompt.length < 1000) {
  throw new Error(`Could not load ${cfg.promptPath} from the repository.`);
}
const pick = (list) => list[Math.floor(Math.random() * list.length)];

let composition = cfg.composition;
let topic = cfg.topic;
let product = null;
if (cfg.product !== 'lateling') {
  const raw = $('Fetch product').first().json.data;
  try {
    product = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) {
    throw new Error(`reels/products/${cfg.product}.json is not valid JSON: ${e.message}`);
  }
  if (!product || product.id !== cfg.product) {
    throw new Error(`Could not load reels/products/${cfg.product}.json from the repository.`);
  }
  // Fall back when the product lacks what a composition needs.
  if (composition === 'ToolDemo' && !(product.screens ?? []).length) composition = 'ToolStory';
  if (composition === 'ToolTrust' && !(product.trust ?? []).length) composition = 'ToolTips';
  if (!topic && (product.angles ?? []).length) topic = pick(product.angles);
}

const lines = [`composition: ${composition}`, `product: ${cfg.product}`];
if (cfg.feature) lines.push(`feature: ${cfg.feature}`);
if (topic) lines.push(`topic: ${topic}`);
if (cfg.store) lines.push(`store: ${cfg.store}`);

// Hooks of recent reels about the same product, read from the release notes the render Action writes.
// Releases from before products existed have no Product line and were all Lateling.
const recent = $('Recent reels').all()
  .map((item) => item.json?.body ?? '')
  .filter((body) => (/^Product: (.+)$/m.exec(body)?.[1]?.trim() ?? 'lateling') === cfg.product)
  .map((body) => /^Hook: (.+)$/m.exec(body)?.[1]?.trim())
  .filter(Boolean)
  .slice(0, 20);
if (recent.length) lines.push('avoid:', ...recent.map((h) => `- ${h}`));
lines.push(`today: ${new Date().toISOString().slice(0, 10)}`);
if (product) lines.push('', '## The product', '', JSON.stringify(product, null, 1));

return [{json: {composition, topic, payload: {
  system_instruction: {parts: [{text: prompt}]},
  contents: [{role: 'user', parts: [{text: lines.join('\n')}]}],
  generationConfig: {responseMimeType: 'application/json', temperature: 1.1},
}}}];

// Reads the props JSON out of Gemini's answer and does a few cheap checks.
// The full schema check happens in the render itself.
const cfg = $('Config').first().json;
const composition = $('Build Gemini request').first().json.composition;
const parts = $json.candidates?.[0]?.content?.parts ?? [];
let text = parts.map((p) => p.text ?? '').join('').trim();
if (!text) throw new Error('Gemini returned no text. Finish reason: ' + ($json.candidates?.[0]?.finishReason ?? 'unknown'));
text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');

let props;
try {
  props = JSON.parse(text);
} catch (e) {
  throw new Error('Gemini did not return valid JSON: ' + e.message);
}
if (!props || typeof props !== 'object' || Array.isArray(props)) throw new Error('Props must be a JSON object.');
if (typeof props.hook !== 'string') throw new Error('Props have no "hook".');

// House style: no em or en dashes anywhere in the on-screen text.
const dashes = JSON.stringify(props).match(/[–—]/g);
if (dashes) throw new Error('Script contains em or en dashes. Run again.');

// Keep the requested feature, and never let the model choose audio files.
if (composition === 'FeatureDemo' && cfg.feature) props.feature = cfg.feature;
if (cfg.product !== 'lateling') props.product = cfg.product;
delete props.audio;

// The post text is for the posting nodes, not for the video, so it is taken out of the props.
const post = props.post && typeof props.post === 'object' ? props.post : {};
delete props.post;
let caption = typeof post.caption === 'string' ? post.caption.trim() : '';
if (!caption) caption = props.hook;
const tags = (Array.isArray(post.hashtags) ? post.hashtags : [])
  .filter((t) => typeof t === 'string')
  .map((t) => '#' + t.replace(/[^\p{L}\p{N}_]/gu, ''))
  .filter((t) => t.length > 1);
const hashtags = [...new Set(tags)].slice(0, 8);
const postText = hashtags.length ? `${caption}\n\n${hashtags.join(' ')}` : caption;
// For X: as many hashtags as fit in 280 characters.
let postTextShort = caption.slice(0, 280);
for (const tag of hashtags) {
  const sep = postTextShort === caption.slice(0, 280) ? '\n\n' : ' ';
  if ((postTextShort + sep + tag).length > 280) break;
  postTextShort += sep + tag;
}

const propsString = JSON.stringify(props);
if (propsString.length > 60000) throw new Error('Props are too long for a workflow input.');

return [{json: {composition, product: cfg.product, requestId: cfg.requestId, hook: props.hook, caption, hashtags, postText, postTextShort, props, propsString}}];

// The finished reel. The posting nodes after this one read from it.
const job = $('Parse props').first().json;
const cfg = $('Config').first().json;
const release = $json.body;
const asset = (release.assets ?? []).find((a) => a.name.endsWith('.mp4'));
if (!asset) throw new Error('The release exists but has no MP4 attached.');

return [{json: {
  videoUrl: asset.browser_download_url,
  fileName: asset.name,
  sizeBytes: asset.size,
  product: job.product,
  composition: job.composition,
  feature: cfg.feature,
  hook: job.hook,
  caption: job.caption,
  hashtags: job.hashtags,
  postText: job.postText,
  postTextShort: job.postTextShort,
  requestId: job.requestId,
  releaseTag: release.tag_name,
  releasePage: release.html_url,
  props: job.props,
}}];

// What was uploaded in this run, and the text for posting it to Instagram by hand.
const reel = $('Reel ready').first().json;
return [{json: {
  product: reel.product,
  hook: reel.hook,
  youtubeUrl: `https://www.youtube.com/shorts/${$json.id}`,
  videoUrl: reel.videoUrl,
  postText: reel.postText,
}}];
